-- perguntas
select public._site_importar_bloco('www.foradopapel.com.br', 'perguntas', '[{"pergunta":"Quanto custa?","resposta":"O valor depende do escopo, das integrações, do conteúdo e do prazo. Depois de uma conversa de 30 minutos, mandamos uma proposta por escrito com tudo o que está incluído.","grupo":"preco","inicio":true},{"pergunta":"Quanto tempo leva?","resposta":"O prazo sai na proposta, junto com as etapas. Depende do escopo e de quando o conteúdo e os acessos chegam do seu lado.","grupo":"preco","inicio":true},{"pergunta":"O diagnóstico é pago?","resposta":"A conversa inicial é gratuita. Em projetos grandes, fazemos antes um diagnóstico pago: como funciona hoje, onde trava e o que resolver primeiro. Se você seguir com o projeto, o valor é abatido.","grupo":"preco","inicio":false},{"pergunta":"E se eu precisar de algo que não estava combinado?","resposta":"Mandamos um orçamento de serviço adicional. Só começamos depois que você aprovar.","grupo":"preco","inicio":false},{"pergunta":"Vocês atendem empresas maiores?","resposta":"Sim. O que define o projeto é o problema, não o tamanho da empresa. Projetos maiores começam por um diagnóstico.","grupo":"trabalho","inicio":false},{"pergunta":"Vocês integram com o sistema que já usamos?","resposta":"Na maioria dos casos, sim. Quando dá, juntamos tudo num sistema só; quando um programa precisa continuar (nota fiscal, banco, pagamento), ligamos ele ao sistema. Confirmamos antes de qualquer proposta.","grupo":"trabalho","inicio":false},{"pergunta":"Vocês usam inteligência artificial?","resposta":"Onde ela poupa tempo de verdade: separar mensagens, sugerir respostas, resumir conversas e combinar horários. Uma pessoa da sua equipe sempre confere e aprova.","grupo":"trabalho","inicio":false},{"pergunta":"O que é a mensalidade?","resposta":"O cuidado depois da entrega, em três níveis: Essencial (no ar e seguro), Evolução (melhorias todo mês) e Parceria (indicadores e reunião mensal). Hospedagem e ferramentas à parte, pelo custo.","grupo":"depois","inicio":true},{"pergunta":"Tem garantia?","resposta":"Sim. Por 30 dias depois da entrega, corrigimos sem custo qualquer falha no que foi combinado.","grupo":"depois","inicio":true},{"pergunta":"O que fica com a minha empresa no fim?","resposta":"Os dados são sempre da sua empresa, e você pode exportá-los quando quiser. O domínio e as contas das ferramentas ficam em nome da sua empresa. Em sites, tudo fica com você no fim. Em sistemas sob medida, o código é nosso e você o usa com uma licença enquanto a mensalidade estiver ativa; se preferir ficar com o código, a proposta diz quanto custa.","grupo":"depois","inicio":true},{"pergunta":"Eu consigo atualizar o site sozinho?","resposta":"Sim. O site tem painel de edição para trocar textos e fotos. Lojas em plataforma pronta têm o painel da própria plataforma.","grupo":"depois","inicio":false}]'::jsonb);

